import{_ as e,r as s,o,c,e as a,a as l,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"表单控制器 - October CMS - 3.x","titleTemplate":false,"description":"为任何后台页面添加表单管理功能。","frontmatter":{"subtitle":"为任何后台页面添加表单管理功能。"},"headers":[{"level":2,"title":"配置表单行为","slug":"配置表单行为","link":"#配置表单行为","children":[{"level":3,"title":"创建页面","slug":"创建页面","link":"#创建页面","children":[]},{"level":3,"title":"更新页面","slug":"更新页面","link":"#更新页面","children":[]},{"level":3,"title":"预览页面","slug":"预览页面","link":"#预览页面","children":[]},{"level":3,"title":"自定义消息","slug":"自定义消息","link":"#自定义消息","children":[]},{"level":3,"title":"权限限制","slug":"权限限制","link":"#权限限制","children":[]}]},{"level":2,"title":"定义表单字段","slug":"定义表单字段","link":"#定义表单字段","children":[]},{"level":2,"title":"表单视图","slug":"表单视图","link":"#表单视图","children":[{"level":3,"title":"创建视图","slug":"创建视图","link":"#创建视图","children":[]},{"level":3,"title":"更新视图","slug":"更新视图","link":"#更新视图","children":[]},{"level":3,"title":"预览视图","slug":"预览视图","link":"#预览视图","children":[]}]},{"level":2,"title":"表单设计","slug":"表单设计","link":"#表单设计","children":[{"level":3,"title":"显示模式","slug":"显示模式","link":"#显示模式","children":[]},{"level":3,"title":"弹出窗口显示模式","slug":"弹出窗口显示模式","link":"#弹出窗口显示模式","children":[]}]},{"level":2,"title":"扩展表单行为","slug":"扩展表单行为","link":"#扩展表单行为","children":[{"level":3,"title":"扩展表单配置","slug":"扩展表单配置","link":"#扩展表单配置","children":[]},{"level":3,"title":"覆盖控制器操作","slug":"覆盖控制器操作","link":"#覆盖控制器操作","children":[]},{"level":3,"title":"覆盖表单保存数据","slug":"覆盖表单保存数据","link":"#覆盖表单保存数据","children":[]},{"level":3,"title":"覆盖控制器重定向","slug":"覆盖控制器重定向","link":"#覆盖控制器重定向","children":[]},{"level":3,"title":"扩展表单模型查询","slug":"扩展表单模型查询","link":"#扩展表单模型查询","children":[]},{"level":3,"title":"扩展表单字段","slug":"扩展表单字段","link":"#扩展表单字段","children":[]},{"level":3,"title":"过滤表单字段","slug":"过滤表单字段","link":"#过滤表单字段","children":[]}]},{"level":2,"title":"验证表单字段","slug":"验证表单字段","link":"#验证表单字段","children":[]}],"relativePath":"3.x/zh-cn/extend/forms/form-controller.md","filePath":"3.x/zh-cn/extend/forms/form-controller.md"}'),u={name:"3.x/zh-cn/extend/forms/form-controller.md"};function i(k,n,d,g,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"表单控制器",-1)),a(p),n[1]||(n[1]=r(`<p><code>Backend\\Behaviors\\FormController</code> 类是一个控制器行为，用于轻松地向后台页面添加表单功能。该行为提供三个页面：创建、更新和预览。预览页面是更新页面的只读版本。当您使用表单行为时，不需要在控制器中定义 <code>create</code>、<code>update</code> 和 <code>preview</code> 操作——行为会自动为您处理。但是，您应该提供相应的视图文件。</p><p>表单行为依赖于表单<a href="./../../element/form-fields.html">字段定义</a>和<a href="./../database/model.html">模型类</a>。要使用表单行为，您应该将其添加到控制器类的 <code>$implement</code> 属性中。同时，应定义 <code>$formConfig</code> 类属性，其值应引用用于配置行为属性的 YAML 文件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>FormController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$formConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_form.yaml&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="custom-block tip"><p>通常表单和<a href="./../lists/list-controller.html">列表控制器</a>会在同一个控制器中一起使用。</p></div><h2 id="配置表单行为"><a href="#配置表单行为" class="header-anchor">#</a> 配置表单行为</h2><p>在 <code>$formConfig</code> 属性中引用的配置文件以 YAML 格式定义。该文件应放置在<a href="./../system/views.html">控制器的视图目录</a>中。以下是一个典型的表单行为配置文件示例。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_form.yaml</span>
<span class="token key atrule">name</span><span class="token punctuation">:</span> Blog Category
<span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/blog/models/post/fields.yaml
<span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Blog\\Post

<span class="token key atrule">create</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> New Blog Post

<span class="token key atrule">update</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Edit Blog Post

<span class="token key atrule">preview</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> View Blog Post
</code></pre></div><p>以下属性在表单配置文件中是必需的。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>name</strong></td><td>此表单管理的对象名称。</td></tr><tr><td><strong>form</strong></td><td>配置数组或表单字段定义文件的引用，参见<a href="./../../element/form-fields.html">表单字段</a>。</td></tr><tr><td><strong>modelClass</strong></td><td>模型类名，表单数据针对此模型进行加载和保存。</td></tr></tbody></table></div><p>以下列出的配置属性是可选的。如果希望表单行为支持创建、更新或预览页面，请定义这些属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>design</strong></td><td>渲染时使用特定的表单设计模式显示表单（见下文）。</td></tr><tr><td><strong>defaultRedirect</strong></td><td>未定义特定重定向页面时用作后备的重定向页面。</td></tr><tr><td><strong>create</strong></td><td>创建页面的配置数组或配置文件引用。</td></tr><tr><td><strong>update</strong></td><td>更新页面的配置数组或配置文件引用。</td></tr><tr><td><strong>preview</strong></td><td>预览页面的配置数组或配置文件引用。</td></tr><tr><td><strong>customMessages</strong></td><td>自定义表单控制器中使用的消息。</td></tr><tr><td><strong>permissions</strong></td><td>对表单控制器提供的某些操作应用限制。</td></tr></tbody></table></div><h3 id="创建页面"><a href="#创建页面" class="header-anchor">#</a> 创建页面</h3><p>要支持创建页面，请在 YAML 文件中添加以下配置。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">create</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> New Blog Post
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/blog/posts/update/<span class="token punctuation">:</span>id
    <span class="token key atrule">redirectClose</span><span class="token punctuation">:</span> acme/blog/posts
</code></pre></div><p>创建页面支持以下属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>页面标题，可引用<a href="./../system/localization.html">本地化字符串</a>。</td></tr><tr><td><strong>redirect</strong></td><td>记录保存时的重定向页面。</td></tr><tr><td><strong>redirectClose</strong></td><td>记录保存且请求中发送了 <strong>close</strong> post 变量时的重定向页面。</td></tr><tr><td><strong>form</strong></td><td>仅覆盖创建页面的默认表单字段定义。</td></tr></tbody></table></div><h3 id="更新页面"><a href="#更新页面" class="header-anchor">#</a> 更新页面</h3><p>要支持更新页面，请在 YAML 文件中添加以下配置。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">update</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Edit Blog Post
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/blog/posts
</code></pre></div><p>更新页面支持以下属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>页面标题，可引用<a href="./../system/localization.html">本地化字符串</a>。</td></tr><tr><td><strong>redirect</strong></td><td>记录保存时的重定向页面。</td></tr><tr><td><strong>redirectClose</strong></td><td>记录保存且请求中发送了 <strong>close</strong> post 变量时的重定向页面。</td></tr><tr><td><strong>form</strong></td><td>仅覆盖更新页面的默认表单字段定义。</td></tr></tbody></table></div><h3 id="预览页面"><a href="#预览页面" class="header-anchor">#</a> 预览页面</h3><p>要支持预览页面，请在 YAML 文件中添加以下配置：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">preview</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> View Blog Post
</code></pre></div><p>预览页面支持以下属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>页面标题，可引用<a href="./../system/localization.html">本地化字符串</a>。</td></tr><tr><td><strong>form</strong></td><td>仅覆盖预览页面的默认表单字段定义。</td></tr></tbody></table></div><h3 id="自定义消息"><a href="#自定义消息" class="header-anchor">#</a> 自定义消息</h3><p>指定 <code>customMessages</code> 属性可覆盖表单控制器使用的默认消息。值可以是纯文本或引用<a href="./../system/localization.html">本地化字符串</a>。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
    <span class="token key atrule">notFound</span><span class="token punctuation">:</span> Did not find the thing
    <span class="token key atrule">flashCreate</span><span class="token punctuation">:</span> New thing created
    <span class="token key atrule">flashUpdate</span><span class="token punctuation">:</span> Updated that thing
    <span class="token key atrule">flashDelete</span><span class="token punctuation">:</span> Thing is gone
</code></pre></div><p>您还可以在显示表单的上下文中修改消息。以下示例将仅覆盖 <code>update</code> 上下文中的 <code>notFound</code> 消息。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">update</span><span class="token punctuation">:</span>
    <span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
        <span class="token key atrule">notFound</span><span class="token punctuation">:</span> Nothing found when updating
</code></pre></div><p>以下消息可作为自定义消息进行覆盖。</p><details class="custom-block details"><summary>查看可用消息列表</summary><div class="table"><table tabindex="0"><thead><tr><th>消息</th><th>默认消息</th></tr></thead><tbody><tr><td><strong>notFound</strong></td><td>Form record with an ID of :id could not be found.</td></tr><tr><td><strong>flashCreate</strong></td><td>:name Created</td></tr><tr><td><strong>flashUpdate</strong></td><td>:name Updated</td></tr><tr><td><strong>flashDelete</strong></td><td>:name Deleted</td></tr></tbody></table></div></details><h3 id="权限限制"><a href="#权限限制" class="header-anchor">#</a> 权限限制</h3><p>指定 <code>permissions</code> 属性可对表单控制器提供的操作应用限制。使用当前后台用户必须拥有的<a href="./../backend/permissions.html">权限值</a>才能使用该字段。支持单个权限的字符串或权限数组（只需满足其中一个即可授予访问权限）。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">permissions</span><span class="token punctuation">:</span>
    <span class="token key atrule">modelCreate</span><span class="token punctuation">:</span> admins.manage.create
    <span class="token key atrule">modelDelete</span><span class="token punctuation">:</span> admins.manage.delete
</code></pre></div><p>以下属性可作为必需权限进行覆盖。</p><details class="custom-block details"><summary>查看可用消息列表</summary><div class="table"><table tabindex="0"><thead><tr><th>消息</th><th>默认消息</th></tr></thead><tbody><tr><td><strong>modelCreate</strong></td><td>创建新记录所需。</td></tr><tr><td><strong>modelUpdate</strong></td><td>修改现有记录所需。</td></tr><tr><td><strong>modelPreview</strong></td><td>预览现有记录所需。</td></tr><tr><td><strong>modelDelete</strong></td><td>删除现有记录所需。</td></tr></tbody></table></div></details><h2 id="定义表单字段"><a href="#定义表单字段" class="header-anchor">#</a> 定义表单字段</h2><div class="custom-block aside"><p>可用的表单字段属性可在<a href="./../../element/form-fields.html">表单字段定义</a>页面找到。</p></div><p>表单字段通过 YAML 文件定义。表单字段配置被表单行为用于创建表单控件并将其绑定到模型字段。</p><p>该文件放置在插件 <strong>models</strong> 目录的子目录中。子目录名称与小写的模型类名匹配。文件名没有限制，但 <strong>fields.yaml</strong> 和 <strong>form_fields.yaml</strong> 是常用名称。表单字段文件位置示例：</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           └── <code>models</code>
|               ├── post  <em>← 配置目录</em>
|               |   └── fields.yaml  <em>← 配置文件</em>
|               └── Post.php  <em>← 模型类</em></p>
</code></pre><p>字段可放置在三个区域中：<strong>外部区域</strong>、<strong>主选项卡</strong>或<strong>次要选项卡</strong>。以下示例展示了表单字段定义文件的典型内容。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># fields.yaml</span>
<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">blog_title</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Blog Title
        <span class="token key atrule">description</span><span class="token punctuation">:</span> The title for this blog

    <span class="token key atrule">published_at</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Published date
        <span class="token key atrule">description</span><span class="token punctuation">:</span> When this blog post was published
        <span class="token key atrule">type</span><span class="token punctuation">:</span> datepicker

    <span class="token comment"># [...]</span>

<span class="token key atrule">tabs</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token comment"># [...]</span>

<span class="token key atrule">secondaryTabs</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token comment"># [...]</span>
</code></pre></div><h2 id="表单视图"><a href="#表单视图" class="header-anchor">#</a> 表单视图</h2><p>对于表单支持的每个页面（创建、更新和预览），您应该提供一个具有对应名称的<a href="./../backend/controllers-ajax.html">视图文件</a>——<strong>create.php</strong>、<strong>update.php</strong> 和 <strong>preview.php</strong>。</p><p>表单行为向控制器类添加两个方法：<code>formRender</code>、<code>formRenderDesign</code> 和 <code>formRenderPreview</code>。这些方法渲染通过上述 YAML 文件配置的表单控件。</p><h3 id="创建视图"><a href="#创建视图" class="header-anchor">#</a> 创建视图</h3><p><strong>create.php</strong> 视图代表允许用户创建新记录的创建页面。典型的创建页面包含面包屑导航、表单本身和表单按钮。<strong>data-request</strong> 属性应引用表单行为提供的 <code>onSave</code> AJAX 处理程序。以下是典型创建视图文件的内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;d-flex flex-column h-100&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>flex-grow-1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>loader-container<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSave<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-data</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ close: true }<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-message</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Creating Category...<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-hotkey</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>ctrl+enter, cmd+enter<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                Create and Close
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>span</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn-text<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                or <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/categories&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Cancel<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>span</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>要跟踪未保存的更改并在离开表单时显示警告，请在表单开始标签上添加 <code>data-change-monitor</code> 属性。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;...&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;data-change-monitor&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="更新视图"><a href="#更新视图" class="header-anchor">#</a> 更新视图</h3><p><strong>update.php</strong> 视图代表允许用户更新或删除现有记录的更新页面。典型的更新页面包含面包屑导航、表单本身和表单按钮。更新页面与创建页面非常相似，但通常多一个删除按钮。<strong>data-request</strong> 属性应引用表单行为提供的 <code>onSave</code> AJAX 处理程序。以下是典型 update.php 表单的内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;d-flex flex-column h-100&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>flex-grow-1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>loader-container<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSave<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-data</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ close: true }<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-message</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Saving Category...<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-hotkey</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>ctrl+enter, cmd+enter<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                Save and Close
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
                <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>oc-icon-trash-o btn-icon danger pull-right<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDelete<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-message</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Deleting Category...<span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-request-confirm</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Do you really want to delete this category?<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>span</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn-text<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                or <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/blog/categories&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Cancel<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>span</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="预览视图"><a href="#预览视图" class="header-anchor">#</a> 预览视图</h3><p><strong>preview.php</strong> 视图代表允许用户以只读模式预览现有记录的预览页面。典型的预览页面包含面包屑导航和表单本身。以下是典型 preview.php 表单的内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-preview<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRenderPreview</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="表单设计"><a href="#表单设计" class="header-anchor">#</a> 表单设计</h2><p><code>create:controller</code> 命令生成<a href="./../system/controllers.html">控制器</a>，并支持 <code>--design</code> 选项来实现所需的显示模式，如下所述。</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:controller Acme.Blog Posts <span class="token parameter variable">--design</span><span class="token operator">=</span>popup
</code></pre></div><p>当您需要在不管理 HTML 内容的情况下显示表单时，表单设计非常有用，这虽然灵活性较低，但可以使构建表单的过程更快。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">design</span><span class="token punctuation">:</span>
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> basic
</code></pre></div><p>行为配置中的 <strong>design</strong> 属性控制表单的显示方式。支持以下属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>displayMode</strong></td><td>指定要使用的显示模式，支持的值：<code>custom</code>、<code>basic</code>、<code>survey</code>、<code>sidebar</code>、<code>popup</code>。默认值：<code>basic</code></td></tr><tr><td><strong>horizontalMode</strong></td><td>以水平方向显示表单字段。默认值：<code>false</code></td></tr><tr><td><strong>surveyMode</strong></td><td>禁用选项卡并在页面上以带标题的分区显示所有字段。默认值：<code>false</code></td></tr><tr><td><strong>size</strong></td><td>页面容器的大小，支持的值：<code>400</code>-<code>1200</code> 之间以 <code>50</code> 为步长递增，<code>auto</code>。默认值：<code>auto</code></td></tr><tr><td><strong>sidebarSize</strong></td><td><code>sidebar</code> 模式下侧边栏的宽度，支持的值：<code>300</code>-<code>750</code> 之间以 <code>50</code> 为步长递增。默认值：<code>300</code></td></tr></tbody></table></div><p>使用 <code>formRenderDesign</code> 方法在 <strong>create.php</strong>、<strong>update.php</strong> 和 <strong>preview.php</strong> 视图文件中渲染表单设计。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formRenderDesign</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="显示模式"><a href="#显示模式" class="header-anchor">#</a> 显示模式</h3><p>在行为配置中使用 <strong>design</strong> 显示模式时，视图内容使用系统提供的标准表单内容生成。</p><p>以下是支持的 <strong>displayMode</strong> 值及其描述。</p><div class="table"><table tabindex="0"><thead><tr><th>显示模式</th><th>描述</th></tr></thead><tbody><tr><td><strong>custom</strong></td><td>使用自定义视图文件渲染表单（默认）</td></tr><tr><td><strong>basic</strong></td><td>标准表单的基本布局</td></tr><tr><td><strong>survey</strong></td><td>使用带标题的堆叠分区的调查布局</td></tr><tr><td><strong>sidebar</strong></td><td>侧边栏布局，次要选项卡在侧面板中渲染</td></tr><tr><td><strong>popup</strong></td><td>表单内容在弹出窗口中管理</td></tr></tbody></table></div><p><strong>size</strong> 属性定义页面容器的大小或弹出窗口的大小。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">design</span><span class="token punctuation">:</span>
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> survey
    <span class="token key atrule">size</span><span class="token punctuation">:</span> <span class="token number">950</span>
</code></pre></div><h3 id="弹出窗口显示模式"><a href="#弹出窗口显示模式" class="header-anchor">#</a> 弹出窗口显示模式</h3><p>如果 <strong>design</strong> 设置为使用 <code>popup</code> 显示模式，则完全不需要创建任何视图文件。所有表单管理功能都包含在弹出窗口中。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">design</span><span class="token punctuation">:</span>
    <span class="token key atrule">displayMode</span><span class="token punctuation">:</span> popup
    <span class="token key atrule">size</span><span class="token punctuation">:</span> <span class="token number">750</span>
</code></pre></div><p>与<a href="./../lists/list-controller.html">列表控制器</a>集成时，将 <strong>recordOnClick</strong> 属性设置为 <code>popup</code> 可在点击记录时打开管理视图。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_list.yaml</span>
<span class="token key atrule">recordOnClick</span><span class="token punctuation">:</span> popup
</code></pre></div><p><strong>recordOnClick</strong> 还支持向表单控制器传递上下文，例如，将值设置为 <code>popup@preview</code> 可使用预览上下文。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># config_list.yaml</span>
<span class="token key atrule">recordOnClick</span><span class="token punctuation">:</span> popup@preview
</code></pre></div><p>可以使用 <code>onLoadPopupForm</code> AJAX 处理程序配合 popup 控件打开创建视图，如下例所示。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>popup<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-handler</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onLoadPopupForm<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-primary<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    New Item
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="扩展表单行为"><a href="#扩展表单行为" class="header-anchor">#</a> 扩展表单行为</h2><p>有时您可能希望修改默认的表单行为，有几种方式可以实现。</p><h3 id="扩展表单配置"><a href="#扩展表单配置" class="header-anchor">#</a> 扩展表单配置</h3><p>您可以使用 <code>formGetConfig</code> 方法动态扩展表单配置。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formGetConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$config</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FormController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">formGetConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">form</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeConfig</span><span class="token punctuation">(</span><span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">form</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Set the active tab dynamically</span>
    <span class="token variable">$config</span><span class="token operator">-&gt;</span><span class="token property">form</span><span class="token operator">-&gt;</span><span class="token property">tabs</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;activeTab&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Activities&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$config</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="覆盖控制器操作"><a href="#覆盖控制器操作" class="header-anchor">#</a> 覆盖控制器操作</h3><p>您可以在控制器中使用自己的逻辑来实现 <code>create</code>、<code>update</code> 或 <code>preview</code> 操作方法，然后可选地调用表单行为的父方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">update</span><span class="token punctuation">(</span><span class="token variable">$recordId</span><span class="token punctuation">,</span> <span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">//</span>
    <span class="token comment">// Do any custom code here</span>
    <span class="token comment">//</span>

    <span class="token comment">// Call the FormController behavior update() method</span>
    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FormController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token variable">$recordId</span><span class="token punctuation">,</span> <span class="token variable">$context</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="覆盖表单保存数据"><a href="#覆盖表单保存数据" class="header-anchor">#</a> 覆盖表单保存数据</h3><p>您可以使用 <code>formBeforeSave</code> 覆盖（或等效方法）在表单保存或更新之前更改保存值。要覆盖字段的保存值，请使用 <code>formSetSaveValue(key, value)</code> 方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formBeforeSave</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// When locale dropdown is set to &quot;custom&quot;, override with the _custom_locale text field</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;MyModel[locale]&#39;</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;custom&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">formSetSaveValue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;locale&#39;</span><span class="token punctuation">,</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;MyModel[_custom_locale]&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="覆盖控制器重定向"><a href="#覆盖控制器重定向" class="header-anchor">#</a> 覆盖控制器重定向</h3><p>您可以通过覆盖 <code>formGetRedirectUrl</code> 方法来指定模型保存后要重定向到的 URL。此方法返回要重定向到的位置，相对 URL 被视为后台 URL。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formGetRedirectUrl</span><span class="token punctuation">(</span><span class="token variable">$context</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">,</span> <span class="token variable">$model</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;https://octobercms.com&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="扩展表单模型查询"><a href="#扩展表单模型查询" class="header-anchor">#</a> 扩展表单模型查询</h3><p>可以通过在控制器类中覆盖 <code>formExtendQuery</code> 方法来扩展表单<a href="./../database/model.html">数据库模型</a>的查询。此示例将确保软删除的记录仍然可以被找到和更新，方法是对查询应用 <strong>withTrashed</strong> 作用域：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formExtendQuery</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">withTrashed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="扩展表单字段"><a href="#扩展表单字段" class="header-anchor">#</a> 扩展表单字段</h3><p>您可以通过绑定 <code>backend.form.extendFields</code> <a href="./../services/event.html">全局事件</a>从外部扩展另一个控制器的字段。事件函数将接收一个 <code>$form</code> 参数，代表 <code>Backend\\Widgets\\Form</code> 对象，您可以使用 <code>getController</code>、<code>getModel</code> 和 <code>getContext</code> 方法来检查执行上下文。</p><p>由于此事件可能影响所有表单，因此必须检查控制器和模型是否为正确的类型。以下是使用 <code>addFields</code> 方法向邮件设置表单添加新字段的示例。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.form.extendFields&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$form</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>
        <span class="token operator">!</span><span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">getController</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>Settings</span> <span class="token operator">||</span>
        <span class="token operator">!</span><span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">getModel</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>System<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>MailSetting</span>
    <span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">addFields</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;my_field&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;My Field&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;comment&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is a custom field I have added.&#39;</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>您还可以通过在控制器类中覆盖 <code>formExtendFields</code> 方法来内部扩展表单字段。这只会影响 <code>FormController</code> 行为使用的表单。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Categories</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>FormController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">formExtendFields</span><span class="token punctuation">(</span><span class="token variable">$form</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$form</span><span class="token operator">-&gt;</span><span class="token function">addFields</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>以下方法在 <code>$form</code> 对象上可用。</p><div class="table"><table tabindex="0"><thead><tr><th>方法</th><th>描述</th></tr></thead><tbody><tr><td><strong>addFields</strong></td><td>向外部区域添加新字段</td></tr><tr><td><strong>addTabFields</strong></td><td>向选项卡区域添加新字段</td></tr><tr><td><strong>addSecondaryTabFields</strong></td><td>向次要选项卡区域添加新字段</td></tr><tr><td><strong>removeField</strong></td><td>从任何区域移除字段</td></tr></tbody></table></div><p>每个方法接受类似于<a href="./../../element/form-fields.html">表单字段配置</a>的字段数组。</p><h3 id="过滤表单字段"><a href="#过滤表单字段" class="header-anchor">#</a> 过滤表单字段</h3><p>如<a href="./field-dependencies.html">字段依赖部分</a>所述，您也可以通过挂钩 <code>form.filterFields</code> 事件来实现通过扩展方式过滤表单字段。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.form.filterFields&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$formWidget</span><span class="token punctuation">,</span> <span class="token variable">$fields</span><span class="token punctuation">,</span> <span class="token variable">$context</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">source_type</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;http&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">source_url</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">git_branch</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token keyword">elseif</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">source_type</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;git&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">source_url</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">git_branch</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token keyword">else</span> <span class="token punctuation">{</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">source_url</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
            <span class="token variable">$fields</span><span class="token operator">-&gt;</span><span class="token property">git_branch</span><span class="token operator">-&gt;</span><span class="token property">hidden</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="验证表单字段"><a href="#验证表单字段" class="header-anchor">#</a> 验证表单字段</h2><p>要验证表单的字段，您可以在模型中使用<a href="./../database/traits.html">验证 Trait</a>。</p>`,114))])}const y=e(u,[["render",i]]);export{v as __pageData,y as default};
